final class Money {
    public function __construct(public readonly int $amount, public readonly string $currency) {}
    public function equals(Money $o): bool {
        return $this->amount === $o->amount && $this->currency === $o->currency;
    }
} // менять нельзя, сравниваем по значению, не по id

class Order { // корень агрегата
    private array $items = [];
    public function addItem(Product $p, int $qty): void {
        if ($this->isClosed()) throw new DomainException('closed');
        $this->items[] = new OrderItem($p, $qty); // правило стережёт корень
    }
}

